-- The changes chinook-mcp-postgresql.sql makes, for the H2 copy of Chinook that the tests build
-- (ChinookDatabase, in MODE=PostgreSQL with DATABASE_TO_LOWER=TRUE, so names match PostgreSQL's). Run as the owner
-- after the upstream Chinook_PostgreSql.sql. Only the syntax differs: H2 redefines a column to make it an
-- identity, and has users rather than login roles.

-- Optimistic lock versions
ALTER TABLE artist   ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE album    ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE track    ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE customer ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE playlist ADD COLUMN version INT DEFAULT 1 NOT NULL;

-- When a track was put on a playlist (NULL for the shipped data)
ALTER TABLE playlist_track ADD COLUMN added_at TIMESTAMP;

-- Generated keys, after the highest key in the 1.4.5 data
ALTER TABLE artist       ALTER COLUMN artist_id       INT GENERATED BY DEFAULT AS IDENTITY (START WITH 276);
ALTER TABLE album        ALTER COLUMN album_id        INT GENERATED BY DEFAULT AS IDENTITY (START WITH 348);
ALTER TABLE track        ALTER COLUMN track_id        INT GENERATED BY DEFAULT AS IDENTITY (START WITH 3504);
ALTER TABLE customer     ALTER COLUMN customer_id     INT GENERATED BY DEFAULT AS IDENTITY (START WITH 60);
ALTER TABLE invoice      ALTER COLUMN invoice_id      INT GENERATED BY DEFAULT AS IDENTITY (START WITH 413);
ALTER TABLE invoice_line ALTER COLUMN invoice_line_id INT GENERATED BY DEFAULT AS IDENTITY (START WITH 2241);
ALTER TABLE playlist     ALTER COLUMN playlist_id     INT GENERATED BY DEFAULT AS IDENTITY (START WITH 19);

-- Accounts. The passwords are the sample's.
CREATE USER IF NOT EXISTS mcp_reader PASSWORD 'reader';
GRANT SELECT ON SCHEMA public TO mcp_reader;

CREATE USER IF NOT EXISTS mcp_store PASSWORD 'store';
GRANT SELECT ON SCHEMA public TO mcp_store;
GRANT INSERT ON artist, album, track, customer, invoice, invoice_line, playlist, playlist_track TO mcp_store;
GRANT UPDATE ON artist, album, track, customer, playlist TO mcp_store;
GRANT DELETE ON playlist, playlist_track TO mcp_store;
